function can(k, ctx) {
  if (isOwner()) return true;
  switch (k) {
    case 'cash':
      return false;
    // 公司現金水位、runway
    case 'allProjects':
      return false;
    // 其他客戶的專案
    case 'projectFinance':
      return myProjects().includes(ctx);
    // §9.6 自己的專案明細看得到
    case 'otherPayroll':
      return false;
    // 他人薪資
    case 'myPayroll':
      return true;
    case 'audit':
      return false;
    case 'budget':
      return myProjects().includes(ctx);
    case 'crm':
      return false;
    default:
      return true;
  }
}
