/* ==================================================================
   v5 AI Collaboration Agent —— Handbook 04.3 的四類訊號
   Observe（讀既有資料）→ Compress（收斂）→ Signal（指出要注意的）
   人保有決定權：Agent 只發訊號，不改狀態、不評價績效（Handbook 04.4）
   ================================================================== */
function buildSignals() {
  const out = [];
  const add = (k, ty, ti, ds, jump) => out.push({
    id: k,
    ty,
    ti,
    ds,
    jump,
    done: DB.signalDone && DB.signalDone[k]
  });
  // ① Issue 逾期或長時間未更新
  DB.issues.filter(i => i.st !== 'Done').forEach(i => {
    if (i.due && i.due < TODAY) add('sig-due-' + i.id, 'overdue', `${i.t} 已逾期`, `到期日 ${i.due}，已過 ${ddiff(i.due, TODAY)} 天。Owner ${person(i.owner)}`, () => openDrawer('issue', i.id));else if (agingRisk(i) === 'crit') add('sig-age-' + i.id, 'stale', `${i.t} 停滯中`, `已開始 ${ageOf(i)} 天，超過 ${i.size} 尺寸的 P85（${sle(i.size).p85}d）`, () => openDrawer('issue', i.id));
  });
  // ② Blocker / Need Decision
  DB.issues.filter(i => i.blocker).forEach(i => add('sig-blk-' + i.id, 'stale', `${i.t} 有 Blocker`, i.blocker, () => openDrawer('issue', i.id)));
  Object.keys(DB.journal).forEach(d => {
    const bs = DB.journal[d].blocks;
    bs.forEach((b, n) => {
      if (b.t === 'h3' && /Need Decision/i.test(b.text)) {
        const kids = [];
        for (let k = n + 1; k < bs.length && bs[k].t !== 'h3' && bs[k].t !== 'h2'; k++) if (bs[k].text.trim()) kids.push(bs[k].text);
        if (kids.length) add('sig-dec-' + d, 'writeback', `${d} 有待決事項`, kids.join('；'), () => {
          S.jday = d;
          nav('journal', 0);
        });
      }
    });
  });
  // ③ Thread 有結論但尚未回寫
  DB.threads.filter(t => !t.closed && t.msgs.length >= 3).forEach(t => add('sig-thr-' + t.id, 'writeback', `Thread「${t.t}」有結論未回寫`, `${t.msgs.length} 則訊息、${t.files.length} 個檔案，尚未填 Close 卡的五欄`, () => {
    S.proj = t.p;
    S.thread = t.id;
    nav('project', 2);
  }));
  // ④ Evidence 尚未留下
  DB.issues.filter(i => i.st === 'Done' && !i.ev).forEach(i => add('sig-ev-' + i.id, 'evidence', `${i.t} 已完成但沒有 Evidence`, 'Handbook 03.3：Done 應能指向某個 observable outcome', () => openDrawer('issue', i.id)));
  // ⑤ 契約衍生：承諾落後
  DB.commitments.filter(c => commitStatus(c) === '落後').forEach(c => add('sig-cmt-' + c.id, 'commit', `承諾落後：${c.t}`, `最近一次紀錄為未履行。Owner ${person(c.owner)}`, () => {
    S.doc = c.doc;
    S.clause = c.clause;
    nav('commit', c.dir === '內部' ? 0 : 1);
  }));
  // ⑥ 缺原始憑證
  const miss = DB.txns.filter(t => !t.v.length);
  if (miss.length) add('sig-vch', 'commit', `${miss.length} 筆交易缺原始憑證`, miss.map(t => t.t).join('、') + '。缺憑證的分錄沒有入帳依據', () => nav('money', 0));
  // ⑦ 出勤紀錄未確認
  (DB.timesheet[DB.me] || []).filter(w => w.st === 'draft' && w.from <= TODAY).forEach(w => add('sig-ts-' + w.wk, 'commit', `${w.wk} 出勤紀錄尚未確認`, '勞基法 §30 要求逐日記載至分鐘並由本人確認，發薪前須完成', () => nav('capacity', 3)));
  return out;
}
DB.signalDone = {};
