/* ==================================================================
   v5 出勤紀錄（勞基法 §30 / 勞動事件法 §38）
   ================================================================== */
const WDAY = ['一', '二', '三', '四', '五', '六', '日'];
const hm = m => `${Math.floor(m / 60)}:${String(m % 60).padStart(2, '0')}`;
function tsWeeks(who) {
  return DB.timesheet[who] || [];
}
function tsTotal(w) {
  return w.days.reduce((a, b) => a + b, 0);
}
function tsMonth(who, ym) {
  return tsWeeks(who).filter(w => w.from.slice(0, 7) === ym || dadd(w.from, 6).slice(0, 7) === ym).reduce((a, w) => a + tsTotal(w), 0);
}
function estimateWeek(who, w) {
  return 0;

  // 從 Issue 事件流推估：該週內有 started/done 的工作，依 Size 給基準分鐘
  const base = {
    S: 120,
    M: 300,
    L: 600
  };
  let total = 0;
  DB.issues.filter(i => i.owner === who).forEach(i => {
    [i.started, i.done].forEach(d => {
      if (d && d >= w.from && d <= dadd(w.from, 6)) total += base[i.size] / 2;
    });
  });
  return Math.round(total);
}

/* ---------- toast + undo ---------- */
let toastSeq = 0;
function toast(msg, undo) {
  const el = document.createElement('div');
  el.className = 'toast';
  const id = ++toastSeq;
  el.innerHTML = `<span>${msg}</span>`;
  if (undo) {
    const b = document.createElement('button');
    b.className = 'undo';
    b.textContent = '復原';
    b.onclick = () => {
      undo();
      render();
      paintFlowBadge();
      el.remove();
      toast('已復原');
    };
    el.appendChild(b);
  }
  const box = $('#toasts');
  box.appendChild(el);
  while (box.children.length > 3) box.firstChild.remove();
  setTimeout(() => {
    el.style.transition = 'opacity .3s';
    el.style.opacity = '0';
    setTimeout(() => el.remove(), 320);
  }, undo ? 5200 : 2400);
}

