function advReimb(id) {
  const target = DB.reimb.find(r => r.id === id);
  if (target && (target.st === '待送' ? target.who !== DB.me : !isOwner())) return deny();
  const r = DB.reimb.find(x => x.id === id),
    i = RSTEPS.indexOf(r.st);
  if (i >= RSTEPS.length - 1) {
    toast('已是最終狀態');
    return;
  }
  const next = RSTEPS[i + 1],
    before = r.st;
  commit('update', '報帳狀態', `${r.t} → ${next}`, () => {
    r.st = next;
    if (next === '已核') {
      const t = {
        id: nid('TXN'),
        d: r.d,
        t: r.t + '（報帳）',
        p: '公司層級',
        cat: '場地',
        amt: -r.amt,
        pass: false,
        v: ['收據'],
        note: '由報帳 ' + r.id + ' 自動產生'
      };
      DB.txns.unshift(t);
      r.txn = t.id;
      return [`核准 → <b>自動在帳本產生一筆支出 ${nt(-r.amt)}</b>`, '憑證「收據」一併帶入', '本月淨額重算'];
    }
    return [`狀態機前進到 <b>${next}</b>`];
  }, () => {
    r.st = before;
    if (r.txn) {
      DB.txns = DB.txns.filter(x => x.id !== r.txn);
      r.txn = null;
    }
  });
}

