/* ----- Evidence Repo ----- */
const REPO_DIRS = ['', '01_contract', '02_discovery', '03_delivery', '04_evidence', '05_finance', '06_retro'];
function ensureRepo(pid) {
  if (DB.repos[pid]) return;
  commit('create', 'Evidence Repo', P(pid).t, () => {
    DB.repos[pid] = {
      version: 'v0.1',
      frozen: false,
      readme: '',
      versions: [{
        v: 'v0.1',
        t: 'Kickoff ' + TODAY,
        st: 'now'
      }],
      tree: [{
        f: 'README.md',
        dir: '',
        note: '待撰寫',
        ok: false
      }, {
        f: 'CHANGELOG.md',
        dir: '',
        note: '自動生成',
        ok: true
      }],
      pending: []
    };
    P(pid).repo = 'v0.1';
    return ['建立六層資料夾骨架', 'README 待撰寫 → 結案檢查 1 項未過', '專案總覽的 Repo 欄位 → v0.1'];
  }, () => {
    delete DB.repos[pid];
    P(pid).repo = '—';
  });
}
function formRepoFile(pid) {
  openForm({
    crumb: 'Evidence',
    title: '加入檔案',
    sub: '把散落在對話、日誌、帳本裡的東西收進來',
    fields: [{
      k: 'f',
      label: '檔名',
      req: true,
      ph: '例如 驗收單_已簽.pdf'
    }, {
      k: 'dir',
      label: '資料夾',
      type: 'select',
      opts: REPO_DIRS.map(d => [d, d || '（根目錄）']),
      req: true
    }, {
      k: 'note',
      label: '說明',
      ph: '這份東西證明了什麼'
    }],
    values: {
      f: '',
      dir: '04_evidence',
      note: ''
    },
    effects: ['Evidence Repo 檔案樹', '結案檢查「驗收證據存在」判定', 'CHANGELOG 新增一筆'],
    onSave: v => {
      const r = DB.repos[pid];
      commit('create', 'Evidence 檔案', v.f, () => {
        r.tree.push({
          f: v.f,
          dir: v.dir,
          note: v.note,
          ok: v.dir === '04_evidence' ? true : null
        });
        return [`${v.dir || '根目錄'} +1 個檔案`, 'CHANGELOG 追加一筆', v.dir === '04_evidence' ? '結案檢查「驗收證據存在」→ <b>通過</b>' : ''].filter(Boolean);
      }, () => r.tree.pop());
    }
  });
}
function delRepoFile(pid, idx) {
  const r = DB.repos[pid],
    f = r.tree[idx];
  if (r.frozen) {
    toast('此版本已凍結，無法修改；請建立新版本');
    return;
  }
  confirmDelete('檔案', f.f, '', () => commit('delete', 'Evidence 檔案', f.f, () => {
    r.tree.splice(idx, 1);
    return ['檔案樹 −1', '結案檢查重新判定'];
  }, () => r.tree.splice(idx, 0, f)));
}
function formReadme(pid) {
  const r = DB.repos[pid];
  openForm({
    crumb: 'README',
    title: '撰寫 README',
    sub: '三個月後另一個人接手，靠的就是這一段',
    fields: [{
      k: 'readme',
      label: '專案敘事',
      type: 'textarea',
      rows: 11,
      req: true,
      ph: '為什麼做這個案子？\n交付了什麼？\n學到什麼、下次怎麼做？'
    }],
    values: {
      readme: r.readme
    },
    effects: ['結案檢查「README 已寫」判定', '可標記 v1.0 的條件'],
    onSave: v => {
      const b = r.readme;
      commit('update', 'README', P(pid).t, () => {
        r.readme = v.readme;
        return ['結案檢查「README 已寫」→ <b>' + (v.readme.trim() ? '通過' : '未通過') + '</b>', '若全部通過，「標記 v1.0」按鈕解鎖'];
      }, () => {
        r.readme = b;
      });
    }
  });
}
function repoChecks(pid) {
  const r = DB.repos[pid],
    p = P(pid);
  return [['README 已寫', !!(r.readme && r.readme.trim())], ['驗收證據存在', r.tree.some(f => f.dir === '04_evidence')], ['成本明細已提供乙方', r.tree.some(f => f.dir === '05_finance')], ['結案回顧已撰寫', r.tree.some(f => f.dir === '06_retro')], ['交付標準已全部確認', p.delivery.length > 0]];
}
function freezeRepo(pid) {
  const r = DB.repos[pid],
    checks = repoChecks(pid);
  if (checks.some(c => !c[1])) {
    toast('還有 <b>' + checks.filter(c => !c[1]).length + '</b> 項結案檢查未通過');
    return;
  }
  typeToConfirm('標記 v1.0 並凍結？', `凍結之後這個版本的內容<b style="color:var(--text)">不能再改</b>，版本快照會保留於本頁記憶體。之後的任何修改只能產生 v1.1。<br><span style="color:var(--text-3)">這個動作不可復原。</span>`, 'v1.0', () => {
    commit('update', 'Evidence Repo', P(pid).t + ' → v1.0 凍結', () => {
      r.frozen = true;
      r.version = 'v1.0';
      r.versions.forEach(v => v.st = 'past');
      r.versions.push({
        v: 'v1.0',
        t: '驗收通過 · 凍結 ' + TODAY,
        st: 'now'
      });
      P(pid).repo = 'v1.0';
      P(pid).status = '已結案';
      return ['版本快照保留於本頁記憶體', '專案狀態 → <b>已結案</b>', '外部承諾仍須依證據確認履行', '之後的修改只能產生 v1.1'];
    });
  });
}
function archivePending(pid, idx) {
  const r = DB.repos[pid],
    pd = r.pending[idx];
  commit('create', 'Evidence 歸檔', pd.what, () => {
    r.pending.splice(idx, 1);
    r.tree.push({
      f: pd.what.replace(/\s/g, '_') + '.md',
      dir: pd.to,
      note: '自 ' + pd.src + ' 歸檔',
      ok: pd.to === '04_evidence' ? true : null
    });
    return [`${pd.to} +1 個檔案`, '待歸檔清單 −1', '結案檢查重新判定'];
  }, () => {
    r.tree.pop();
    r.pending.splice(idx, 0, pd);
  });
}

