function formAlloc(who) {
  if (who !== DB.me) return deny();
  const rows = DB.capacity[who];
  openForm({
    crumb: '容量',
    title: '調整週配置 · ' + person(who),
    sub: '百分比，不是工時。合計應為 100%',
    fields: rows.map((r, i) => ({
      k: 'a' + i,
      label: r[0] + (r[2] != null ? `（約定 ${r[2]}%）` : ''),
      type: 'number',
      req: true,
      half: true
    })),
    values: Object.fromEntries(rows.map((r, i) => ['a' + i, r[1]])),
    effects: ['週配置堆疊條', '容量配置承諾（契約 §2.4）的履行判定', '目標對齊的投入比例'],
    onSave: v => {
      const before = rows.map(r => r[1]);
      const sum = rows.reduce((a, r, i) => a + (Number(v['a' + i]) || 0), 0);
      commit('update', '週配置', person(who), () => {
        rows.forEach((r, i) => r[1] = Number(v['a' + i]) || 0);
        const ef = [`合計 <b>${sum}%</b>${sum !== 100 ? '　<span style="color:var(--warn)">不等於 100%</span>' : ''}`];
        rows.forEach(r => {
          if (r[2] != null && Math.abs(r[1] - r[2]) >= 10) ef.push(`<b>${esc(r[0])}</b> 偏離約定方向 ${Math.abs(r[1] - r[2])}pt → 承諾 C-014 判定為需檢討`);
        });
        return ef;
      }, () => rows.forEach((r, i) => r[1] = before[i]));
    }
  });
}

/* ----- ClickUp 式關聯 / 子任務 / 自訂欄位 ----- */
const RELTY = {
  block: ['ty-block', '擋住了'],
  wait: ['ty-wait', '等待中'],
  link: ['ty-link', '相關'],
  doc: ['ty-doc', '文件']
};
function formRel(id) {
  if (id && !editable(ISS(id))) return deny();
  const i = ISS(id);
  const others = DB.issues.filter(x => x.id !== id).map(x => [x.id, x.id + ' ' + x.t]);
  const docs = DB.docs.map(d => ['DOC:' + d.id, d.t]);
  openForm({
    crumb: '關聯',
    title: '新增關聯',
    sub: i.t,
    fields: [{
      k: 'ty',
      label: '關聯類型',
      type: 'chips',
      opts: [['block', '擋住了'], ['wait', '等待中'], ['link', '相關'], ['doc', '文件']],
      req: true,
      hint: '「擋住了」＝這件事做完別人才能動；「等待中」＝要先等對方'
    }, {
      k: 'target',
      label: '對象',
      type: 'select',
      opts: [...others, ...docs],
      req: true
    }],
    values: {
      ty: 'link',
      target: others.length ? others[0][0] : 'DOC:D1'
    },
    effects: ['工作抽屜的關聯區塊', '清單／看板上的 ⇄ 標記', '被擋住的一方也會看到反向關聯'],
    onSave: v => {
      const isDoc = v.target.startsWith('DOC:');
      const tid = isDoc ? v.target.slice(4) : v.target;
      const tt = isDoc ? (DB.docs.find(d => d.id === tid) || {}).t : (ISS(tid) || {}).t;
      const r = {
        ty: isDoc ? 'doc' : v.ty,
        id: tid,
        t: tt
      };
      commit('create', '關聯', `${i.t} ${RELTY[r.ty][1]} ${tt}`, () => {
        i.rel = i.rel || [];
        i.rel.push(r);
        const ef = [`<b>${esc(i.t)}</b> 新增一條「${RELTY[r.ty][1]}」關聯`];
        if (!isDoc && (v.ty === 'block' || v.ty === 'wait')) {
          const o = ISS(tid);
          if (o) {
            o.rel = o.rel || [];
            o.rel.push({
              ty: v.ty === 'block' ? 'wait' : 'block',
              id: i.id,
              t: i.t
            });
            ef.push(`<b>${esc(o.t)}</b> 自動加上反向關聯「${v.ty === 'block' ? '等待中' : '擋住了'}」`);
          }
        }
        ef.push('清單／看板的 ⇄ 標記更新');
        return ef;
      }, () => {
        i.rel.pop();
      });
    }
  });
}
function delRel(id, idx) {
  if (id && !editable(ISS(id))) return deny();
  const i = ISS(id),
    r = i.rel[idx];
  commit('delete', '關聯', `${i.t} ⇄ ${r.t}`, () => {
    i.rel.splice(idx, 1);
    return ['關聯移除', '反向關聯需另行移除'];
  }, () => i.rel.splice(idx, 0, r));
  if (S.stack.length) paintDrawer();
}
