/* ---- caret 工具 ---- */
function caretOff(el) {
  const s = selection();
  if (!s.rangeCount) return 0;
  const r = s.getRangeAt(0).cloneRange();
  const m = document.createRange();
  m.selectNodeContents(el);
  m.setEnd(r.endContainer, r.endOffset);
  return m.toString().length;
}
function setCaret(el, off) {
  if (!el) return;
  el.focus();
  const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  let n,
    acc = 0;
  while (n = w.nextNode()) {
    if (acc + n.length >= off) {
      const r = document.createRange();
      r.setStart(n, Math.max(0, off - acc));
      r.collapse(true);
      const s = selection();
      s.removeAllRanges();
      s.addRange(r);
      return;
    }
    acc += n.length;
  }
  const r = document.createRange();
  r.selectNodeContents(el);
  r.collapse(false);
  const s = selection();
  s.removeAllRanges();
  s.addRange(r);
}
function focusB(id, off) {
  runtime._afterRender = () => {
    const el = root.querySelector(`.eb[data-id="${id}"] .eb-tx`);
    if (el) setCaret(el, off == null ? el.innerText.length : off);
    S.curBlock = id;
  };
}
function syncAll() {
  if (!canWriteJournal()) return;
  root.querySelectorAll('#doc .eb-tx[data-id]').forEach(el => {
    const b = bOf(el.dataset.id);
    if (b && TEXTY(b.t)) b.text = el.innerText.replace(/\n$/, '');
  });
}

