/* ==================================================================
   輸入層（v5 重寫）
   1. IME 守衛：中文輸入法組字期間 keydown 會以 keyCode 229 送出，
      任何結構性處理都必須先看 e.isComposing；組字中也絕不重繪 DOM，
      否則注音／倉頡打到一半會吃字。這是 v4 最大的真實風險。
   2. Markdown 快捷：「# 」「- 」「[] 」「> 」是比叫選單更快的輸入路徑。
   3. Undo：以區塊快照堆疊實作，⌘Z / ⌘⇧Z。
   4. @ 引用既有物件（# 是建立新的）。
   ================================================================== */
let COMPOSING = false;
function docComposeStart() {
  if (!canWriteJournal()) return;
  COMPOSING = true;
  closeSummon();
}
function docComposeEnd(e) {
  if (!canWriteJournal()) return;
  COMPOSING = false;
  const tx = e.target.closest && e.target.closest('.eb-tx');
  if (!tx) return;
  const b = bOf(tx.dataset.id);
  if (b) b.text = tx.innerText.replace(/\n$/, '');
  checkTrigger(tx, b); // 組字結束後才判斷 # / @
}

/* ---- Undo ---- */
let UNDO = [],
  REDO = [];
function snap() {
  if (!canWriteJournal()) return;
  UNDO.push(JSON.stringify(jdoc().blocks));
  if (UNDO.length > 50) UNDO.shift();
  REDO = [];
}
function undo() {
  if (!canWriteJournal()) return;
  if (!UNDO.length) {
    toast('沒有可復原的編輯');
    return;
  }
  REDO.push(JSON.stringify(jdoc().blocks));
  jdoc().blocks = JSON.parse(UNDO.pop());
  render();
  toast('已復原編輯　<b>⌘⇧Z</b> 重做');
}
function redo() {
  if (!canWriteJournal()) return;
  if (!REDO.length) return;
  UNDO.push(JSON.stringify(jdoc().blocks));
  jdoc().blocks = JSON.parse(REDO.pop());
  render();
}

/* ---- Markdown 快捷 ---- */
const MD = [[/^#\s$/, 'h1'], [/^##\s$/, 'h2'], [/^###\s$/, 'h3'], [/^[-*]\s$/, 'bullet'], [/^\[\]\s$/, 'todo'], [/^\[\s\]\s$/, 'todo'], [/^>\s$/, 'quote'], [/^```$/, 'code'], [/^---$/, 'divider']];
function tryMarkdown(b, tx) {
  for (const [re, ty] of MD) {
    if (re.test(b.text)) {
      snap();
      if (ty === 'divider') {
        const i = bIdx(b.id),
          arr = blks();
        b.t = 'divider';
        b.text = '';
        const nb = {
          id: newBid(),
          t: 'p',
          ind: b.ind,
          text: ''
        };
        arr.splice(i + 1, 0, nb);
        focusB(nb.id, 0);
      } else {
        b.t = ty;
        b.text = '';
        if (ty === 'todo') b.done = false;
        focusB(b.id, 0);
      }
      render();
      return true;
    }
  }
  return false;
}

/* ---- 觸發字元偵測（# 召喚 / @ 引用） ---- */
function checkTrigger(tx, b) {
  if (!b || COMPOSING) return;
  const off = caretOff(tx),
    upto = b.text.slice(0, off);
  const mh = upto.match(/(?:^|\s)#([^\s#@]{0,24})$/);
  const ma = upto.match(/(?:^|\s)@([^\s#@]{0,24})$/);
  if (mh) {
    const start = off - mh[1].length - 1,
      rect = caretRect(tx);
    if (!SM.open || SM.blockId !== b.id || SM.mode !== 'hash') openSummon(b.id, start, mh[1], rect, 'hash');else {
      SM.q = mh[1];
      SM.hits = summonHits(mh[1]);
      SM.sel = 0;
      paintSummon();
    }
  } else if (ma) {
    const start = off - ma[1].length - 1,
      rect = caretRect(tx);
    if (!SM.open || SM.blockId !== b.id || SM.mode !== 'at') openSummon(b.id, start, ma[1], rect, 'at');else {
      SM.q = ma[1];
      SM.hits = mentionHits(ma[1]);
      SM.sel = 0;
      paintSummon();
    }
  } else if (SM.open) closeSummon();
}
function caretRect(tx) {
  const s = selection();
  if (s.rangeCount) {
    const r = s.getRangeAt(0).getBoundingClientRect();
    if (r.width || r.height) return r;
  }
  return tx.getBoundingClientRect();
}

/* ---- @ 引用既有物件 ---- */
function mentionHits(q) {
  q = (q || '').toLowerCase();
  const out = [];
  const push = (ty, rid, nm, ds, ic) => {
    if (!q || (nm + rid + ds).toLowerCase().includes(q)) out.push({
      mention: true,
      ty,
      rid,
      k: rid,
      nm,
      ds,
      ic,
      g: {
        issue: '工作項目',
        project: '專案',
        txn: '交易',
        decision: '決策',
        event: '時間線事件'
      }[ty]
    });
  };
  DB.issues.forEach(i => push('issue', i.id, i.t, `${i.id} · ${i.st} · ${person(i.owner)}`, 'issue'));
  DB.projects.forEach(p => push('project', p.id, p.t, `${p.id} · ${p.status}`, 'project'));
  DB.txns.forEach(t => push('txn', t.id, t.t, `${t.d} · ${nt(t.amt)}`, 'txn'));
  DB.decisions.forEach(d => push('decision', d.id, d.t, `${d.id} · ${d.st}`, 'commit'));
  DB.events.forEach(e => push('event', e.id, e.t, `${e.d} · ${e.layer}層`, 'timeline'));
  (DB.docObjects || []).forEach(d => push('doc_object', d.id, d.title || d.type, `${d.day} · ${person(d.author)}`, 'journal'));
  return out.slice(0, 40);
}

/* ---- 鍵盤 ---- */
function docKey(e) {
  if (!canWriteJournal()) return;
  const tx = e.target.closest('.eb-tx');
  if (!tx) return;
  if (e.isComposing || COMPOSING || e.keyCode === 229) return; // ← IME 守衛
  const id = tx.dataset.id,
    b = bOf(id);
  if (!b) return;
  const i = bIdx(id),
    arr = blks(),
    off = caretOff(tx),
    len = tx.innerText.length;
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z') {
    e.preventDefault();
    syncAll();
    e.shiftKey ? redo() : undo();
    return;
  }
  if (SM.open) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      SM.sel = Math.min(SM.sel + 1, SM.hits.length - 1);
      paintSummon();
      return;
    }
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      SM.sel = Math.max(SM.sel - 1, 0);
      paintSummon();
      return;
    }
    if (e.key === 'Enter' || e.key === 'Tab') {
      e.preventDefault();
      applySummon(SM.sel);
      return;
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      closeSummon();
      return;
    }
  }
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    syncAll();
    snap();
    if (!b.text.trim() && b.ind > 0) {
      b.ind--;
      focusB(id, 0);
      render();
      return;
    }
    if (!b.text.trim() && b.t !== 'p') {
      b.t = 'p';
      focusB(id, 0);
      render();
      return;
    }
    const before = b.text.slice(0, off),
      after = b.text.slice(off);
    b.text = before;
    const keep = ['bullet', 'todo'];
    const nt2 = keep.includes(b.t) ? b.t : 'p';
    const nb = {
      id: newBid(),
      t: nt2,
      ind: b.ind,
      text: after,
      done: false
    };
    arr.splice(i + 1, 0, nb);
    focusB(nb.id, 0);
    render();
    return;
  }
  if (e.key === 'Tab') {
    e.preventDefault();
    syncAll();
    snap();
    if (e.shiftKey) {
      if (b.ind > 0) b.ind--;
    } else {
      const prev = arr[i - 1];
      const max = prev ? Math.min(5, prev.ind + 1) : 0;
      if (b.ind < max) b.ind++;
    }
    focusB(id, off);
    render();
    return;
  }
  if (e.key === 'Backspace' && off === 0 && !selection().toString()) {
    syncAll();
    if (b.ind > 0) {
      e.preventDefault();
      snap();
      b.ind--;
      focusB(id, 0);
      render();
      return;
    }
    if (b.t !== 'p') {
      e.preventDefault();
      snap();
      b.t = 'p';
      focusB(id, 0);
      render();
      return;
    }
    if (i > 0) {
      e.preventDefault();
      snap();
      const prev = arr[i - 1];
      if (!TEXTY(prev.t)) {
        arr.splice(i - 1, 1);
        focusB(id, 0);
        render();
        return;
      }
      const cut = prev.text.length;
      prev.text += b.text;
      arr.splice(i, 1);
      focusB(prev.id, cut);
      render();
      return;
    }
  }
  if (e.key === 'ArrowUp' && off === 0) {
    for (let k = i - 1; k >= 0; k--) if (TEXTY(arr[k].t)) {
      e.preventDefault();
      syncAll();
      focusB(arr[k].id, arr[k].text.length);
      render();
      return;
    }
  }
  if (e.key === 'ArrowDown' && off === len) {
    for (let k = i + 1; k < arr.length; k++) if (TEXTY(arr[k].t)) {
      e.preventDefault();
      syncAll();
      focusB(arr[k].id, 0);
      render();
      return;
    }
  }
}
function docInput(e) {
  if (!canWriteJournal()) return;
  if (COMPOSING) return; // ← 組字中不處理
  const tx = e.target.closest('.eb-tx');
  if (!tx) return;
  const b = bOf(tx.dataset.id);
  if (!b) return;
  b.text = tx.innerText.replace(/\n$/, '');
  if (tryMarkdown(b, tx)) return;
  checkTrigger(tx, b);
}
function docClick(e) {
  if (!canWriteJournal()) return;
  if (e.target.id !== 'doc' && !(e.target.dataset && e.target.dataset.docSec)) return;
  syncAll();
  const arr = blks(),
    last = arr[arr.length - 1];
  if (TEXTY(last.t) && !last.text.trim()) {
    focusB(last.id, 0);
    render();
    return;
  }
  snap();
  const nb = {
    id: newBid(),
    t: 'p',
    ind: 0,
    text: ''
  };
  arr.push(nb);
  focusB(nb.id, 0);
  render();
}

/* ---- 拖曳排序（連同子階層一起搬） ---- */
let DRAGB = null;
function subtreeLen(i) {
  const arr = blks(),
    base = arr[i].ind;
  let n = 1;
  while (i + n < arr.length && arr[i + n].ind > base) n++;
  return n;
}
function dragBlk(e, id) {
  if (!canWriteJournal()) return;
  DRAGB = id;
  e.dataTransfer.effectAllowed = 'move';
  const el = root.querySelector(`.eb[data-id="${id}"]`);
  if (el) el.classList.add('dragging');
}
function dragEnd() {
  DRAGB = null;
  root.querySelectorAll('.eb').forEach(el => el.classList.remove('dragging', 'dropbefore', 'dropafter'));
}
function dragOver(e, id) {
  if (!DRAGB || id === DRAGB) return;
  e.preventDefault();
  const el = e.currentTarget,
    r = el.getBoundingClientRect(),
    after = e.clientY > r.top + r.height / 2;
  el.classList.toggle('dropafter', after);
  el.classList.toggle('dropbefore', !after);
}
function dropBlk(e, id) {
  if (!canWriteJournal()) return;
  e.preventDefault();
  if (!DRAGB || id === DRAGB) {
    dragEnd();
    return;
  }
  const el = e.currentTarget,
    r = el.getBoundingClientRect(),
    after = e.clientY > r.top + r.height / 2;
  syncAll();
  snap();
  const arr = blks(),
    si = bIdx(DRAGB),
    n = subtreeLen(si),
    moved = arr.splice(si, n);
  let ti = bIdx(id);
  if (ti < 0) {
    arr.splice(si, 0, ...moved);
    dragEnd();
    render();
    return;
  }
  if (after) ti += subtreeLen(ti);
  const delta = arr[Math.min(ti, arr.length - 1)] ? 0 : 0;
  arr.splice(ti, 0, ...moved);
  dragEnd();
  commit('update', '日誌區塊', '搬移 ' + (moved[0].text || moved[0].t), () => [`連同底下 ${n - 1} 個子階層一起搬`, '順序是資料的一部分，會寫進稽核軌跡']);
}

/* ---- 套用召喚 ---- */
const TPL = {
  standup: {
    h: 'Standup',
    secs: ['Yesterday', 'Today', 'Blocker', 'Need Decision']
  },
  '1on1': {
    h: '1:1 檢核',
    secs: ['近況', '進展與證據', '阻礙', '需要公司支持', '下次檢核前要做的']
  },
  meeting: {
    h: '會議紀錄',
    secs: ['出席', '議題', '決議', '待辦', '未解問題']
  },
  retro: {
    h: '回顧',
    secs: ['做得好', '做不好', '下次改什麼']
  },
  research: {
    h: '研究筆記',
    secs: ['問題', '來源', '發現', '對我們的意義']
  }
};
function applySummon(n) {
  if (!canWriteJournal()) return;
  const h = SM.hits[n];
  if (!h) return;
  const b = bOf(SM.blockId),
    i = bIdx(SM.blockId),
    arr = blks();
  syncAll();
  snap();
  if (h.mention) {
    const keepM = (b.text.slice(0, SM.start) + b.text.slice(SM.start + 1 + SM.q.length)).replace(/\s+$/, '');
    closeSummon();
    b.text = keepM;
    replaceWithObj(b.id, h.ty, h.rid);
    commit('create', '引用', h.nm, () => ['嵌入<b>既有</b>物件，沒有建立新資料', '卡片顯示即時狀態；反向連結會出現在該物件的抽屜']);
    return;
  }
  // 把 #token 從文字裡拿掉
  const keep = (b.text.slice(0, SM.start) + b.text.slice(SM.start + 1 + SM.q.length)).replace(/\s+$/, '');
  closeSummon();
  const k = h.k;
  if (TPL[k]) {
    const docObj = createDocObject(k, S.jday || TODAY, TPL[k]);
    b.text = keep;
    if (!keep.trim()) {
      arr.splice(i, 1);
    }
    const at = keep.trim() ? i + 1 : i;
    const newBlock = {
      id: newBid(),
      t: 'obj',
      ind: b.ind,
      obj: {
        ty: 'doc_object',
        rid: docObj.id
      }
    };
    arr.splice(at, 0, newBlock);
    commit('create', '日誌物件', TPL[k].h, () => [`建立 <b>${TPL[k].h}</b> 獨立物件卡片`, '具備獨立空白畫布專注撰寫，日誌同步即時預覽', '點選卡片右上 ↗ 可隨時進入畫布編輯']);
    render();
    openDrawer('doc_object', docObj.id);
    return;
  }
  if (['h1', 'h2', 'h3', 'p', 'bullet', 'todo', 'quote', 'code'].includes(k)) {
    b.t = k;
    b.text = keep;
    if (k === 'todo') b.done = false;
    focusB(b.id, keep.length);
    render();
    return;
  }
  if (k === 'divider') {
    b.text = keep;
    const nb = {
        id: newBid(),
        t: 'divider',
        ind: b.ind,
        text: ''
      },
      nb2 = {
        id: newBid(),
        t: 'p',
        ind: b.ind,
        text: ''
      };
    if (!keep.trim()) {
      arr.splice(i, 1, nb, nb2);
    } else {
      arr.splice(i + 1, 0, nb, nb2);
    }
    focusB(nb2.id, 0);
    render();
    return;
  }
  // 物件類：開表單，存檔後把這一行變成物件區塊
  b.text = keep;
  summonObject(k, b.id, keep);
  render();
}
function replaceWithObj(blockId, ty, rid) {
  if (!canWriteJournal()) return;
  const b = bOf(blockId);
  if (!b) return;
  const arr = blks(),
    i = bIdx(blockId);
  if (b.text.trim()) {
    const nb = {
      id: newBid(),
      t: 'obj',
      ind: b.ind + 0,
      text: '',
      obj: {
        ty,
        rid
      }
    };
    arr.splice(i + 1, 0, nb);
    const after = {
      id: newBid(),
      t: 'p',
      ind: b.ind,
      text: ''
    };
    arr.splice(i + 2, 0, after);
    focusB(after.id, 0);
  } else {
    b.t = 'obj';
    b.obj = {
      ty,
      rid
    };
    const after = {
      id: newBid(),
      t: 'p',
      ind: b.ind,
      text: ''
    };
    arr.splice(i + 1, 0, after);
    focusB(after.id, 0);
  }
  render();
}
