/* ---- 區塊選項 ---- */
function blockMenu(id) {
  if (!canWriteJournal()) return;
  const b = bOf(id);
  const turn = ['p', 'h1', 'h2', 'h3', 'todo', 'quote', 'code', 'divider'];
  openModal('區塊選項', `目前型別：<b style="color:var(--text)">${b.t}</b>`, `<div class="flab" style="margin-bottom:6px">轉換成</div>
     <div class="chipset" style="margin-bottom:12px">${turn.map(t => `<button class="${b.t === t ? 'on' : ''}" ${bind("click", (event, element) => {
    closeModal();
    turnInto(id, t);
  })}>${t}</button>`).join('')}</div>
     <div class="chipset"><button ${bind("click", (event, element) => {
    closeModal();
    dupBlock(id);
  })}>${svg('copy', 12)} 複製這一行</button></div>`, `<button class="btn" ${bind("click", (event, element) => {
    closeModal();
  })}>取消</button><button class="btn dgr" ${bind("click", (event, element) => {
    closeModal();
    delBlock(id);
  })}>${svg('trash')} 刪除</button>`);
}
function turnInto(id, t) {
  if (!canWriteJournal()) return;
  syncAll();
  const b = bOf(id);
  b.t = t;
  if (t === 'todo' && b.done == null) b.done = false;
  focusB(id, null);
  render();
}
function dupBlock(id) {
  if (!canWriteJournal()) return;
  syncAll();
  const b = bOf(id),
    i = bIdx(id);
  const c = {
    ...b,
    id: newBid()
  };
  blks().splice(i + 1, 0, c);
  focusB(c.id, null);
  render();
}
function delBlock(id) {
  if (!canWriteJournal()) return;
  syncAll();
  const arr = blks(),
    i = bIdx(id),
    b = arr[i];
  commit('delete', '日誌區塊', b.t === 'obj' ? '嵌入物件' : b.text || '（空行）', () => {
    arr.splice(i, 1);
    return b.t === 'obj' ? ['日誌移除這張卡片', '<b>被引用的物件不受影響</b> —— 日誌只是它誕生的地方'] : ['日誌 −1 區塊'];
  }, () => arr.splice(i, 0, b));
  const prev = arr[Math.max(0, i - 1)];
  if (prev && TEXTY(prev.t)) focusB(prev.id, null);
  render();
}

