VIEWS.capacity = tab => {
  if (tab === 0) {
    return guide('<b>週配置是百分比，不是工時。</b>兩人公司排不出人天，但排得出注意力比例。淺色直線是契約 §2.4 的約定方向，色塊是實際 —— 差距本身就是月營運會議的議題。') + `<div class="g g2">${['yz', 'lily'].map(k => panel('Weekly Capacity · ' + person(k), k === 'lily' ? '對照契約 §2.4' : '負責人無工時上限', vAlloc(k) + `<div class="note" style="margin-top:8px">${k === 'lily' ? `本月工時 <b>${hoursUsed()} / 130 h</b>　·　WIP <b>${wip()} / 3</b>　·　距 143h（110%）警戒線尚遠` : 'Management 若長期超過 10%，代表交付工作沒有真的移交出去。'}</div>`, `<button class="btn sm" ${bind("click", (event, element) => {
      formAlloc(k);
    })}>${svg('pen')} 調整</button>`)).join('')}</div>
      <div style="height:12px"></div>
      ${panel('工作項目只要六欄', '不填 Estimate、不填 Actual', `<div class="tbl-wrap"><table class="tbl">
        <thead><tr><th>Task</th><th>Project</th><th>Size</th><th>Status</th><th>Started</th><th>Done</th><th>Age</th><th></th></tr></thead>
        <tbody>${DB.issues.map(i => `<tr ${bind("click", (event, element) => {
      openDrawer('issue', i.id);
    })}>
          <td class="k">${esc(i.t)}</td><td>${P(i.p) ? esc(P(i.p).t.split('·')[0].trim()) : '—'}</td>
          <td>${sizeChip(i.size)}</td><td>${stChip(i.st)}</td><td>${i.started || '—'}</td><td>${i.done || '—'}</td>
          <td>${i.st === 'Done' ? '<span class="m">—</span>' : ageChip(i)}</td>
          <td><span class="rowacts">${mini('pen', (event, element) => {
      formIssue(i.id);
    })}</span></td></tr>`).join('')}</tbody>
      </table></div>`, `<button class="btn pri" ${bind("click", (event, element) => {
      formIssue();
    })}>${svg('plus')} 新增</button>`, true)}`;
  }
  if (tab === 1) {
    const avg = throughputAvg().toFixed(1);
    return guide("<b>Little's Law：平均 WIP ＝ 平均 Throughput × 平均 Cycle Time。</b>三個數字是同一個系統的三個面，所以放在一起看。樣本不足 30 筆時，介面會誠實說「樣本不足」，不給假的 P85。", 'w') + `<div class="kpis" style="margin-bottom:12px">
        <div class="kpi"><div class="lb">Throughput</div><div class="v">${avg}<span style="font-size:12px;color:var(--text-3)"> 件/週</span></div><div class="s">近 ${DB.weekly.length} 週平均</div></div>
        <div class="kpi"><div class="lb">目前 WIP</div><div class="v" style="color:${wip() > 3 ? 'var(--warn)' : 'var(--text)'}">${wip()}<span style="font-size:12px;color:var(--text-3)"> / 3</span></div><div class="s">契約 §2.5 上限</div></div>
        <div class="kpi"><div class="lb">推得平均 Cycle Time</div><div class="v">${(wip() / (throughputAvg() / 7)).toFixed(1)}<span style="font-size:12px;color:var(--text-3)"> 天</span></div><div class="s">WIP ÷ Throughput</div></div>
        <div class="kpi"><div class="lb">停滯中</div><div class="v" style="color:${DB.issues.filter(i => i.st !== 'Done' && agingRisk(i) === 'crit').length ? 'var(--danger)' : 'var(--text)'}">${DB.issues.filter(i => i.st !== 'Done' && agingRisk(i) === 'crit').length}</div><div class="s">age 超過同尺寸 P85</div></div>
      </div>
      ${vWeekly()}<div style="height:12px"></div>${vScatter()}<div style="height:12px"></div>${vAging()}`;
  }
  if (tab === 3) return timesheetView();
  const rem = DB.issues.filter(i => i.st !== 'Done').length;
  return guide('<b>預測輸出的是機率，不是日期。</b>Monte Carlo 用近 9 週的實際 throughput 重抽樣 4000 次。對內規劃看 P50，對客戶承諾用 P85。') + vForecast(Math.max(1, rem), '2026-10-31') + `<div style="height:12px"></div>` + vForecast(12, '2026-11-15') + `<div style="height:12px"></div>
      <div class="hint w">${svg('bolt', 13)}<div><b>這頁在 2027 Q1 之前不應該上線。</b>樣本要 8–12 週才夠。但 <code style="font-family:var(--mono);color:var(--teal)">Issue.started_at / done_at</code> 必須第一天就存在 —— 資料從第一天開始收，介面晚半年再做。整份路線圖唯一一個「欄位先行、介面後補」的例外。</div></div>`;
};

