/* ==================================================================
   出勤紀錄（勞基法 §30、勞動事件法 §38）
   設計原則：
   1. 逐日記載「至分鐘為止」——法定要求，不是產品選擇。
   2. 系統先從 Issue 事件流「推估」，由本人調整後「確認」——不是打卡監控。
   3. 確認後在發薪前可更正，更正留痕；發薪後鎖定。
   4. 與「容量分析」嚴格分離：出勤紀錄是法遵文件，容量是管理視角。
      契約 §20.4 禁止以工作負荷資料作為不利人事決定之依據。
   ================================================================== */
function timesheetView() {
  const who = isOwner() ? S.tsWho : DB.me;
  const ws = tsWeeks(who);
  const mo = tsMonth(who, '2026-09');
  const alert143 = mo > 143 * 60;
  return guide('<b>這一頁是法遵文件，不是管理儀表板。</b>勞基法 §30 要求逐日記載至分鐘、保存五年；勞動事件法 §38 進一步規定：出勤紀錄上的時間<b>推定</b>為經雇主同意執行職務 —— 舉證責任在雇主。所以它必須由本人確認，而且更正要留痕。', 'i') + (isOwner() ? `<div class="seg" style="margin-bottom:12px">${Object.keys(DB.people).map(k => `<button class="${who === k ? 'on' : ''}" ${bind("click", (event, element) => {
    S.tsWho = k;
    render();
  })}>${person(k)}</button>`).join('')}</div>` : '') + `<div class="kpis" style="margin-bottom:12px">
      <div class="kpi"><div class="lb">9 月累計</div><div class="v">${(mo / 60).toFixed(1)}<span style="font-size:12px;color:var(--text-3)"> / ${who === 'lily' ? '130' : '—'} h</span></div>
        ${who === 'lily' ? `<div class="meter"><i style="width:${Math.min(100, mo / 60 / 130 * 100)}%;background:${alert143 ? 'var(--warn)' : 'var(--ok)'}"></i></div>` : ''}
        <div class="s">${who === 'lily' ? '約定正常工時 130h（契約 §4.1）' : '負責人無工時上限'}</div></div>
      <div class="kpi"><div class="lb">143h 警戒</div><div class="v" style="color:${alert143 ? 'var(--warn)' : 'var(--text)'}">${alert143 ? '已觸發' : '未觸發'}</div>
        <div class="s">達 110%（143h）且連續二個月 → 次月營運會議須檢討工時／WIP／報酬（§4.5）</div></div>
      <div class="kpi"><div class="lb">待確認週數</div><div class="v">${ws.filter(w => w.st === 'draft').length}</div>
        <div class="s">發薪前須完成確認</div></div>
      <div class="kpi"><div class="lb">保存期限</div><div class="v">5 <span style="font-size:12px;color:var(--text-3)">年</span></div>
        <div class="s">勞基法 §30 第 5 項</div></div>
    </div>
    ${panel('逐週出勤紀錄', '逐日記載至分鐘為止', `<div class="tsheet"><table class="ts">
      <thead><tr><th>週次</th>${WDAY.map(d => `<th>週${d}</th>`).join('')}<th class="num">合計</th><th>狀態</th><th></th></tr></thead>
      <tbody>${ws.map((w, wi) => `
        <tr class="${w.st === 'locked' ? 'locked' : ''}">
          <td class="k">${w.wk}<span style="display:block;font-size:10.5px;color:var(--text-3);font-family:var(--mono)">${w.from.slice(5)}起</span></td>
          ${w.days.map((m, di) => `<td class="num">${w.st === 'draft' ? `<input type="text" value="${m ? hm(m) : ''}" placeholder="${w.est[di] ? hm(w.est[di]) : '—'}"
                 ${bind("change", (event, element) => {
    setDay(who, wi, di, element.value);
  })}>` : m ? hm(m) : '—'}</td>`).join('')}
          <td class="num" style="color:var(--text)">${(tsTotal(w) / 60).toFixed(1)}h</td>
          <td><span class="tsbadge ts-${w.st === 'draft' ? 'draft' : w.st === 'confirmed' ? 'conf' : 'lock'}">${w.st === 'draft' ? '推估中' : w.st === 'confirmed' ? '本人已確認' : '已鎖定'}</span>
            ${w.conf ? `<span style="display:block;font-size:10px;color:var(--text-3);font-family:var(--mono)">${w.conf}</span>` : ''}</td>
          <td>${w.st === 'draft' ? `<button class="btn sm pri" ${bind("click", (event, element) => {
    confirmWeek(who, wi);
  })}>確認</button>` : w.st === 'confirmed' ? `<button class="btn sm" ${bind("click", (event, element) => {
    amendWeek(who, wi);
  })}>更正</button>` : `<span class="masked">${svg('lock', 11)} 發薪後鎖定</span>`}</td></tr>`).join('')}
      </tbody></table></div>`, `<button class="btn sm" ${bind("click", (event, element) => {
    estimateAll(who);
  })}>${svg('bolt')} 從 Issue 事件流重新推估</button>`, true)}
    <div style="height:12px"></div>
    <div class="lawbox">
      <b>為什麼是「推估 → 本人確認」而不是打卡？</b><br>
      勞基法 §30 並未強制打卡：<span class="ref">「簽到簿、出勤卡、刷卡機、門禁卡、生物特徵辨識系統、電腦出勤紀錄系統或其他可資覈實記載出勤時間之工具」</span>皆可。
      對遠距為主、每週僅兩次現場 cowork 的部分工時工作者（契約 §4.3、§5.1），打卡既不可行也無意義。<br><br>
      這裡的做法是：系統依 Issue 的 started／done 事件先給一個<b>推估值</b>，本人調整後<b>確認</b>——確認的動作本身就是「可資覈實」的紀錄。發薪前可更正（更正會留在稽核軌跡），發薪後鎖定。<br><br>
      <b>刻意不做的事：</b>不偵測滑鼠鍵盤、不截圖、不記錄線上狀態。契約 §20.4 明定健康、負荷感受之資料不得作為考核、升遷、調薪或終止契約之依據；本頁資料只用於工時與工資計算，不進入容量分析的個人評價。
    </div>`;
}
function setDay(who, wi, di, v) {
  if (who !== DB.me) return deny();
  if (tsWeeks(who)[wi]?.st === 'locked') return deny();
  const w = tsWeeks(who)[wi];
  let m = 0;
  if (/^\d{1,2}:\d{1,2}$/.test(v)) {
    const [a, b] = v.split(':');
    m = +a * 60 + +b;
  } else if (/^\d+(\.\d+)?$/.test(v)) m = Math.round(parseFloat(v) * 60);
  const o = w.days[di];
  w.days[di] = m;
  audit('出勤紀錄', `${w.wk} 週${WDAY[di]}`, 'minutes', o ? hm(o) : '—', m ? hm(m) : '—');
}
function estimateAll(who) {
  toast('尚無出勤來源可推估；請填寫實際每日時間，再由本人確認。');
  return;
  const ws = tsWeeks(who).filter(w => w.st === 'draft');
  commit('update', '出勤紀錄', '重新推估 ' + who, () => {
    ws.forEach(w => {
      const t = estimateWeek(who, w);
      const wd = [0, 1, 2, 3, 4].map(() => Math.round(t / 5));
      w.est = [...wd, 0, 0];
      w.days = w.days.map((d, i) => d || w.est[i] || 0);
    });
    return [`${ws.length} 週的推估值已更新`, '推估只是起點 —— 仍須本人確認才具備覈實效力'];
  });
}
function confirmWeek(who, wi) {
  if (who !== DB.me) return deny();
  if (tsWeeks(who)[wi]?.st === 'locked') return deny();
  const w = tsWeeks(who)[wi];
  openModal('確認本週出勤紀錄', `<b style="color:var(--text)">${w.wk}　合計 ${(tsTotal(w) / 60).toFixed(1)} 小時</b><br>
     確認之後，這份紀錄依<span style="color:var(--info)">勞動事件法 §38</span> 推定為經雇主同意執行職務之時間。<br>
     <span style="color:var(--text-3)">發薪前仍可更正，更正會留在稽核軌跡。</span>`, '', `<button class="btn" ${bind("click", (event, element) => {
    closeModal();
  })}>取消</button>
     <button class="btn pri" ${bind("click", (event, element) => {
    closeModal();
    doConfirmWeek(who, wi);
  })}>我確認這週的出勤紀錄</button>`);
}
function doConfirmWeek(who, wi) {
  if (who !== DB.me) return deny();
  if (tsWeeks(who)[wi]?.st === 'locked') return deny();
  const w = tsWeeks(who)[wi];
  commit('update', '出勤紀錄', w.wk + ' 已確認', () => {
    w.st = 'confirmed';
    w.conf = TODAY;
    const mo = tsMonth(who, '2026-09');
    const ef = [`${w.wk} 標記為本人已確認`, `9 月累計 → <b>${(mo / 60).toFixed(1)} h</b>`, '依勞動事件法 §38 推定為經雇主同意執行職務之時間'];
    if (who === 'lily' && mo > 143 * 60) ef.push('<b style="color:var(--warn)">已達 143h（110%）</b> → 若連續二月，次月營運會議須檢討（§4.5）');
    const ot = Math.max(0, mo - 130 * 60);
    if (ot > 0) ef.push(`延長工時 ${(ot / 60).toFixed(1)}h × NT$230.77 → 人事分頁加班費 <b>${nt(ot / 60 * 230.77)}</b>`);
    return ef;
  }, () => {
    w.st = 'draft';
    w.conf = '';
  });
}
function amendWeek(who, wi) {
  if (who !== DB.me) return deny();
  if (tsWeeks(who)[wi]?.st === 'locked') return deny();
  const w = tsWeeks(who)[wi];
  openForm({
    crumb: '更正',
    title: '更正出勤紀錄',
    sub: `${w.wk}　更正理由會寫入稽核軌跡`,
    fields: [{
      k: 'why',
      label: '更正理由',
      req: true,
      ph: '例如：週三實際到 19:30，原紀錄漏登'
    }],
    values: {
      why: ''
    },
    effects: ['該週狀態退回「推估中」可重新編輯', '更正理由與前後值寫入稽核軌跡', '發薪後即無法更正（§30 紀錄完整性）'],
    onSave: v => commit('update', '出勤紀錄', w.wk + ' 更正', () => {
      const o = w.st;
      w.st = 'draft';
      audit('出勤紀錄', w.wk, '更正理由', '已確認', v.why);
      return ['退回可編輯狀態', '更正理由已寫入稽核軌跡 —— 這是勞檢時證明紀錄可信的關鍵'];
    }, () => {
      w.st = 'confirmed';
    })
  });
}

