// 找到 #doc 的結束位置（計算 div 深度，不依賴空白格式）。
function rqDocEnd(html) {
  const start = html.indexOf('id="doc"');
  if (start < 0) return -1;
  let i = html.indexOf('>', start) + 1,
    depth = 1;
  const re = /<\/?div\b[^>]*>/g;
  re.lastIndex = i;
  let m;
  while (m = re.exec(html)) {
    if (m[0][1] === '/') {
      depth--;
      if (depth === 0) return m.index;
    } else if (!m[0].endsWith('/>')) depth++;
  }
  return -1;
}

